-- 93034 Valley of Bones (level 38, required 35) -- Wowhead Forever page
DELETE FROM `quest_template` WHERE `ID`=93034;
INSERT INTO `quest_template` (`ID`,`QuestType`,`QuestPackageID`,`ContentTuningID`,`QuestSortID`,`QuestInfoID`,`SuggestedGroupNum`,`RewardNextQuest`,`RewardXPDifficulty`,`RewardXPMultiplier`,`RewardMoneyDifficulty`,`RewardMoneyMultiplier`,`RewardBonusMoney`,`RewardSpell`,`StartItem`,`Flags`,`AllowableRaces`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog`,`RewardFactionID1`,`RewardFactionOverride1`) VALUES (93034,2,0,0,16651,0,0,0,1,1,0,1,0,0,0,8,0,'Valley of Bones','Improve your reputation with the Gelkis, and locate Nerlokh near the Valley of Bones far east of Gelkis Village.','One of our scouts returned to the village while you were away, with news that confirmed my fears.$B$BThe Magram are up to something, $N. It is not good.$B$BThe Valley of Bones far to the east is a cursed land that few centaur dared to enter and fewer still ever return home. Our enemy has found something there, something evil, and we need to learn what it is.$B$BSeek out the scout Nerlokh at the southern entrance, but you may have to prove yourself further to the Gelkis.','','',92,12500);
DELETE FROM `quest_objectives` WHERE `QuestID`=93034;
INSERT INTO `quest_objectives` (`ID`,`QuestID`,`Type`,`Order`,`StorageIndex`,`ObjectID`,`Amount`,`ConditionalAmount`,`Flags`,`Flags2`,`ProgressBarWeight`,`ParentObjectiveID`,`Visible`,`Description`,`VerifiedBuild`) VALUES (9303400,93034,6,0,0,92,9000,0,0,0,0,0,1,'',0);
