INSERT INTO `quest_template_addon` (`ID`,`MaxLevel`,`AllowableClasses`,`PrevQuestID`) VALUES (93034,0,0,1373);
DELETE FROM `quest_request_items` WHERE `ID`=93034;
DELETE FROM `quest_offer_reward` WHERE `ID`=93034;
INSERT INTO `quest_offer_reward` (`ID`,`RewardText`,`VerifiedBuild`) VALUES (93034,'Behold, the Valley of Bones. Forever cursed, a place where not even the great Theradras would smile upon. No clan had dared to step hoof in this place for generations, yet now the Magram seem to have claimed it as their own!$B$BI am poorly trained and unequipped for combat--these arches are the farthest I will go. You, $N, must fight on behalf of the Gelkis.$B$BYou have done much for us, but your work has only begun.',0);
