INSERT INTO `quest_template` (`ID`,`QuestType`,`QuestPackageID`,`ContentTuningID`,`QuestSortID`,`QuestInfoID`,`SuggestedGroupNum`,`RewardNextQuest`,`RewardXPDifficulty`,`RewardXPMultiplier`,`RewardMoneyDifficulty`,`RewardMoneyMultiplier`,`RewardBonusMoney`,`RewardSpell`,`StartItem`,`Flags`,`AllowableRaces`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog`,`RewardFactionID1`,`RewardFactionOverride1`) VALUES (93037,2,0,0,16651,0,0,0,4,1,0,1,0,0,0,8,0,'Outing Outcasts','Maintain your reputation with the Gelkis Clan, and bring 1 Necromantic Garb to Nerlokh at the entrance of the Valley of Bones.','While I waited for your arrival, I peered a bit further between the arches and noticed something I need you to confirm for me.$B$BI cannot bear saying it aloud. Not until my suspicions have been proven true.$B$B$N, while you are getting your bearings in the valley, slay some of the necromancers that look weaker than the others. Tear off their ritual garb, carefully, and bring it to me. I must know whether I am of clear mind and vision.','','',92,50000);
