INSERT INTO `quest_request_items` (`ID`,`CompletionText`,`VerifiedBuild`) VALUES (93037,'You have my word that I will share my suspicion with you once you have completed the task.$B$BFor the sake of our clan, let us hope my eyes were playing tricks on me.',0);
DELETE FROM `quest_offer_reward` WHERE `ID`=93037;
INSERT INTO `quest_offer_reward` (`ID`,`RewardText`,`VerifiedBuild`) VALUES (93037,'<Nerlokh swiftly takes the cloth and accessories from you and his expression grows cold. After observing only a few from the collection, he sets the rest aside.>$B$B$N. These lesser necromancers are Gelkis.$B$BI see now why our clan seems to be losing numbers more frequently than our skirmishes would indicate. Some among us are defecting, presumably in effort to impress the Magram.$B$BOur clan is losing this war.',0);
