DELETE FROM `quest_template` WHERE `ID`=93224;
INSERT INTO `quest_template` (`ID`,`QuestType`,`QuestPackageID`,`ContentTuningID`,`QuestSortID`,`QuestInfoID`,`SuggestedGroupNum`,`RewardNextQuest`,`RewardXPDifficulty`,`RewardXPMultiplier`,`RewardMoneyDifficulty`,`RewardMoneyMultiplier`,`RewardBonusMoney`,`RewardSpell`,`StartItem`,`Flags`,`AllowableRaces`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog`) VALUES (93224,2,0,0,405,0,0,0,4,1,0,1,0,0,0,8,4294967373,'Carved Centaur Totems','Acquire 5 Carved Centaur Totems by slaying centaur of any clan throughout Desolace, then return them to Captain Pentigast at Nijel''s Point.','It likely comes as no surprise to you that both of the centaur clans are hesitant to accept aid from anyone outside of their clan. This is especially true for folks like you and me - you know, non-centaurs.$B$BOne thing we all have in common is an understanding that money is power, and we have learned that the local centaur barter with carved wood. If you bring me a few samples of their designs, I can put in a rush order for similar etchings. Perhaps we can buy ourselves an advantage.','','');
