INSERT INTO `quest_offer_reward` (`ID`,`RewardText`,`VerifiedBuild`) VALUES (93224,'I am no centaur, but this looks to be a sufficient bundle of totems. Putting myself in their horseshoes, I would be delighted to be gifted this. I even managed to secure a few more while you were out.$B$BSpeak with me when you are ready to make the delivery--I trust you to make the right choice with the clan we side with.',0);
