INSERT INTO `quest_template` (`ID`,`QuestType`,`QuestPackageID`,`ContentTuningID`,`QuestSortID`,`QuestInfoID`,`SuggestedGroupNum`,`RewardNextQuest`,`RewardXPDifficulty`,`RewardXPMultiplier`,`RewardMoneyDifficulty`,`RewardMoneyMultiplier`,`RewardBonusMoney`,`RewardSpell`,`StartItem`,`Flags`,`AllowableRaces`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog`) VALUES (93225,2,0,0,405,0,0,0,4,1,0,1,0,0,0,8,8589934770,'Carved Centaur Totems','Acquire 5 Carved Centaur Totems by slaying centaur of any clan throughout Desolace, then return them to Gurda Wildmane at Ghost Walker Post.','I have noticed that centaur from different clans sometimes gather away from settlements and engage in trade. I have observed this across numerous nights and seemingly with every clan; most importantly I have seen the currency they use: carved totems.$B$BI believe we can turn the tides in our favor with either the Gelkis or the Magram if we deliver a heavy bundle of totems right to them. I have already begun carving some, but I doubt they will be easily fooled without a few authentic ones.','','');
