-- 93227 Buying Friendship: Gelkis (level 45, required 30) -- Wowhead Forever page
DELETE FROM `quest_template` WHERE `ID`=93227;
INSERT INTO `quest_template` (`ID`,`QuestType`,`QuestPackageID`,`ContentTuningID`,`QuestSortID`,`QuestInfoID`,`SuggestedGroupNum`,`RewardNextQuest`,`RewardXPDifficulty`,`RewardXPMultiplier`,`RewardMoneyDifficulty`,`RewardMoneyMultiplier`,`RewardBonusMoney`,`RewardSpell`,`StartItem`,`Flags`,`AllowableRaces`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog`,`RewardFactionID1`,`RewardFactionOverride1`,`ItemDrop1`,`ItemDropQuantity1`) VALUES (93227,2,0,0,405,0,0,0,1,1,0,1,0,0,257685,0,4294967373,'Buying Friendship: Gelkis','Bring the Totem Tote to the Gelkis Quartermaster at Gelkis Village in the Desolace to significantly increase your reputation with that clan. You must be of at least Neutral standing with the Gelkis Clan Centaur.','At first glance, I would wager that the Gelkis are struggling. Their numbers are far fewer than the Magram, and I rarely hear of them stomping around from our scouts.$B$BNonetheless, they are one of the dominant clans in the Desolace and survive to this day. They must be doing something right.$B$BIf you want to make peace with the Gelkis, take this tote of totems with you to Gelkis Village far to the southwest. Primitive as they may be, they are likely to have a treasurer of some kind.','','',92,300000,257685,1);
