INSERT INTO `quest_request_items` (`ID`,`CompletionText`,`VerifiedBuild`) VALUES (93227,'An outsider this deep in the village? You best be bringing business.',0);
DELETE FROM `quest_offer_reward` WHERE `ID`=93227;
INSERT INTO `quest_offer_reward` (`ID`,`RewardText`,`VerifiedBuild`) VALUES (93227,'<Molkar peeks into the bag. A smirk tugs on his lips, which paused only briefly as he caught a glimpse of a clearly fake totem. He pretends to not see it.>$B$BI do not know what possessed an outsider to bring our clan such a gift. It is a great boon for our people, as the Magram Clan have been unusually vicious as of late.$B$BYou no longer need to tread carefully in our village. I will inform Uthek, who will speak with the Khan.',0);
