INSERT INTO `quest_template` (`ID`,`QuestType`,`QuestPackageID`,`ContentTuningID`,`QuestSortID`,`QuestInfoID`,`SuggestedGroupNum`,`RewardNextQuest`,`RewardXPDifficulty`,`RewardXPMultiplier`,`RewardMoneyDifficulty`,`RewardMoneyMultiplier`,`RewardBonusMoney`,`RewardSpell`,`StartItem`,`Flags`,`AllowableRaces`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog`) VALUES (93663,2,0,0,8,0,0,0,3,1,0,1,0,0,0,8,8589934770,'Lost in Transit','Find the missing courier, and ensure Dar''s shipment is delivered to the Harborage.','The draenei of the Harborage are skilled fishermen, and willing to trawl more dangerous waters than I. We occasionally trade. They give us some of their catch, and I offer some of our extra supplies.$B$BI''d sent a goblin courier to deliver my latest shipment, but he never returned. A crocolisk likely made a meal of him.$B$BMore importantly, my business reputation is at stake. That shipment must be found, and delivered to the harborage. Please, find it if you can. Check near the waters along the road.','','');
