INSERT INTO `quest_template` (`ID`,`QuestType`,`QuestPackageID`,`ContentTuningID`,`QuestSortID`,`QuestInfoID`,`SuggestedGroupNum`,`RewardNextQuest`,`RewardXPDifficulty`,`RewardXPMultiplier`,`RewardMoneyDifficulty`,`RewardMoneyMultiplier`,`RewardBonusMoney`,`RewardSpell`,`StartItem`,`Flags`,`AllowableRaces`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog`,`RewardFactionID1`,`RewardFactionOverride1`,`ItemDrop1`,`ItemDropQuantity1`) VALUES (94872,2,0,0,405,0,0,0,1,1,0,1,0,0,257685,0,8589934770,'Buying Friendship: Magram','Bring the Totem Tote to the Magram Quartermaster at Magram Village in the Desolace to significantly increase your reputation with that clan. You must be of at least Neutral standing with the Magram Clan Centaur.','The fierce Magram are undoubtedly winning the war of territories at the moment. While we can all be thankful the clashes haven''t erupted too frequently throughout the desert, every day their village just to the east grows a little bigger; their soldiers a little bolder.$B$BI worry gravely about the consequences of an unchecked Magram clan, but I cannot deny their potential as an ally.$B$BIf you wish to earn their trust, offer this sack of totems to their quartermaster, but be careful.','','',93,300000,257685,1);
