INSERT INTO `quest_offer_reward` (`ID`,`RewardText`,`VerifiedBuild`) VALUES (94872,'<Gorhak''s eyes widen as you offer up the bundle of carved totems, but his brow furrows as his eyes flick back up toward you.>$B$BI am no fool, outsider. This donation is not without cause. You want something, either from me or from our clan. I do not know what.$B$B<With a single swipe of his hand, the quartermaster claims the bag as his own.>$B$BAnd today, I do not care what your ulterior motive might be.$B$BWelcome to Magram Village, outsider.',0);
