INSERT INTO `quest_offer_reward` (`ID`,`RewardText`,`VerifiedBuild`) VALUES (96988,'Cracked. Cracked. CRACKED.$B$BI can''t make use of any of these! I said disable the sentries, not obliterate them! How dangerous could they have been?$B$BMy dreams of magus abominations are at a standstill. For now.',0);
