-- 97539 Silky Sutures (level 36, required 30) -- Wowhead Forever page
DELETE FROM `quest_template` WHERE `ID`=97539;
INSERT INTO `quest_template` (`ID`,`QuestType`,`QuestPackageID`,`ContentTuningID`,`QuestSortID`,`QuestInfoID`,`SuggestedGroupNum`,`RewardNextQuest`,`RewardXPDifficulty`,`RewardXPMultiplier`,`RewardMoneyDifficulty`,`RewardMoneyMultiplier`,`RewardBonusMoney`,`RewardSpell`,`StartItem`,`Flags`,`AllowableRaces`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog`,`RewardFactionID1`,`RewardFactionOverride1`) VALUES (97539,2,0,0,45,0,0,0,5,1,0,1,0,0,0,8,8589934770,'Silky Sutures','Return 12 Surgical Spidersilk to Doctor Gregory Victor in Hammerfall, Arathi Highlands.','This encampment is being left to rot. The siege damage stands, unrepaired, as if neglect were policy. I won''t permit that same decay here. The infirmary answers to me, and I intend to keep it functional.$B$BWe are nearly out of supplies. I''m going to need more equipment--enough to keep the workers and guards on their feet.$B$BUnder pressure, we can make quite an effective field suture using twisted spider silk.$B$B$C, bring me some from the spiders that stalk these highlands.','','',76,10000);
