-- 97985 Thundering Hearts (level 33, required 25) -- Wowhead Forever page
DELETE FROM `quest_template` WHERE `ID`=97985;
INSERT INTO `quest_template` (`ID`,`QuestType`,`QuestPackageID`,`ContentTuningID`,`QuestSortID`,`QuestInfoID`,`SuggestedGroupNum`,`RewardNextQuest`,`RewardXPDifficulty`,`RewardXPMultiplier`,`RewardMoneyDifficulty`,`RewardMoneyMultiplier`,`RewardBonusMoney`,`RewardSpell`,`StartItem`,`Flags`,`AllowableRaces`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog`,`RewardFactionID1`,`RewardFactionOverride1`) VALUES (97985,2,0,0,1497,1,0,0,6,1,0,1,0,0,0,8,8589934770,'Thundering Hearts','Slay Stormheart in Thousand Needles and acquire its heart.','Fascinating, aren''t they? This is the first time I have ever been privy to the secrets of abomination creation.$B$BI have been studying these notes, and it appears we need a heart. A massive one!$B$BI hear there is a thunder lizard there of impressive size called Stormheart, that patrols along the canyon edge in Thousand Needles. With a name like that it must have the perfect heart. I must have that heart!$B$BOh, also I suggest you bring friends. Stormheart isn''t known for being docile.','','',68,15000);
