INSERT INTO `quest_request_items` (`ID`,`CompletionText`,`VerifiedBuild`) VALUES (97985,'Oh, you''ve returned in one piece! Pity, if you hadn''t your flesh and organs would have made excellent fodder for my tinkering.',0);
DELETE FROM `quest_offer_reward` WHERE `ID`=97985;
INSERT INTO `quest_offer_reward` (`ID`,`RewardText`,`VerifiedBuild`) VALUES (97985,'Excellent! I can hardly contain my excitement. Oh, and the heart still has electrical pulses? That''s impressive. I won''t have to shock it back to life then!$B$BThis heart will be a wonderful addition to the abomination, and certainly looks to be the specified size, if these notes are correct.$B$BAh, I love it when a plan comes together.',0);
