INSERT INTO `quest_offer_reward` (`ID`,`RewardText`,`VerifiedBuild`) VALUES (98209,'The Nord''el survived? It cannot be... after all these years!$B$BOur goddess is most wonderful indeed!$B$BYou have my thanks for delivering it here. It is a rare light in the dark times we have had of late, and a symbol of not only Elune''s grace, but of the enduring will of our people to persevere without our immortality.$B$BI will see to it that it is transported safely to Darnassus, so that it may be properly cultivated.',0);
