INSERT INTO `quest_template` (`ID`,`QuestType`,`QuestPackageID`,`ContentTuningID`,`QuestSortID`,`QuestInfoID`,`SuggestedGroupNum`,`RewardNextQuest`,`RewardXPDifficulty`,`RewardXPMultiplier`,`RewardMoneyDifficulty`,`RewardMoneyMultiplier`,`RewardBonusMoney`,`RewardSpell`,`StartItem`,`Flags`,`AllowableRaces`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog`,`RewardChoiceItemID1`,`RewardChoiceItemQuantity1`,`RewardChoiceItemID2`,`RewardChoiceItemQuantity2`,`RewardChoiceItemID3`,`RewardChoiceItemQuantity3`,`ItemDrop1`,`ItemDropQuantity1`) VALUES (98310,2,0,0,11,1,0,0,6,1,0,1,0,0,280394,0,4294967373,'Gleaning Our Future','Use the Goaz Stone near Ados, Modr, Golm, and Neru and bring their hearts back to Prospector Whelgar.','There are other, larger golems all around the Wetlands. They each bear inscriptions marking them as Ados, Modr, Golm, and Neru--matching the missing pieces of the Goaz Stone you found!$B$BI''d be willing to bet if we can bring pieces of them as well, we''ll reveal more of the Goaz Stone!$B$BYou''ll find Ados at the Dragonmaw Gates to the east, near Grim Batol. Modr is right outside Dun Modr to the north. Golm lies beneath Grim Batol, east of Dun Algaz. Neru''s behind Direforge Hill, to the northeast.','','',281319,1,281320,1,281321,1,280394,1);
