INSERT INTO `quest_offer_reward` (`ID`,`RewardText`,`VerifiedBuild`) VALUES (98310,'By Magni''s beard, they''re beautiful! Wait a second, do you see that?! Hold the hearts closer to the Goaz Stone for a moment...$B$B<New text reveals itself on the stone in a faint shimmering light.>$B$BHmm, it''s hard to make out. "Curse of Flesh... they will fail." What''s that supposed to mean?!$B$BWe''ve got to get this somewhere safe so we can study it further!',0);
